<?php $methods=json_decode((string)($settings['payment_methods_json']??''),true);if(!is_array($methods))$methods=['Cash','Bank','Online Transfer','Cheque','JazzCash','Easypaisa','Other']; ?>
<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><span class="module-eyebrow">Monthly billing</span><h1>Fee Automation</h1><p>Configure repeat-safe monthly invoices and admission-month billing.</p></div><form method="post" action="<?= url('/admin/fees/generate-monthly') ?>" class="filter-bar filter-bar--compact"><?= csrf_field() ?><input class="module-input" type="month" name="month" value="<?= date('Y-m') ?>" required><button class="btn btn--primary" type="submit"><i data-lucide="refresh-cw"></i>Generate now</button></form></header>
<section class="module-card"><div class="module-card__header"><div><h2>Billing policy</h2><p>The scheduled command uses these settings; manual generation is always idempotent.</p></div></div><form class="module-card__body module-form" method="post" action="<?= url('/admin/fees/automation') ?>"><?= csrf_field() ?><div class="module-form-grid module-form-grid--three"><div class="module-field"><label>Monthly generation day</label><input class="module-input" type="number" min="1" max="28" name="generation_day" value="<?= (int)($settings['generation_day']??1) ?>" required></div><div class="module-field"><label>Due day</label><input class="module-input" type="number" min="1" max="28" name="due_day" value="<?= e($settings['due_day']??'') ?>" placeholder="Optional"></div><div class="module-field"><label>New admission billing</label><select class="module-select" name="admission_month_policy"><option value="current_month" <?= ($settings['admission_month_policy']??'current_month')==='current_month'?'selected':'' ?>>Generate current month</option><option value="next_month" <?= ($settings['admission_month_policy']??'')==='next_month'?'selected':'' ?>>Start next month</option></select></div><div class="module-field"><label>Voucher copies</label><select class="module-select" name="voucher_copies"><option value="single">Single copy</option><option value="student_institute" <?= ($settings['voucher_copies']??'')==='student_institute'?'selected':'' ?>>Student + Institute</option><option value="three_copy" <?= ($settings['voucher_copies']??'')==='three_copy'?'selected':'' ?>>Student + Institute + Bank</option></select></div><div class="module-field" style="grid-column:span 2"><label>Payment methods</label><input class="module-input" name="payment_methods" value="<?= e(implode(', ',$methods)) ?>" required><small>Comma-separated methods shown during collection.</small></div></div><button class="btn btn--primary" type="submit">Save billing policy</button></form></section>
<section class="module-card"><div class="module-card__header"><div><h2>Generation history</h2><p>Each run records generated and safely skipped invoices.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Month</th><th>Source</th><th>Generated</th><th>Already existed</th><th>Triggered by</th><th>Run at</th></tr></thead><tbody><?php if(!$runs):?><tr><td colspan="6"><div class="compact-empty"><h3>No generation runs</h3><p>Generate a billing month when you are ready.</p></div></td></tr><?php else:foreach($runs as$r):?><tr><td><strong><?= e($r['billing_month']) ?></strong></td><td><?= e(ucfirst($r['source'])) ?></td><td><?= (int)$r['generated_count'] ?></td><td><?= (int)$r['skipped_count'] ?></td><td><?= e($r['triggered_by_name']?:'Scheduler') ?></td><td><?= e($r['created_at']) ?></td></tr><?php endforeach;endif?></tbody></table></div></section></div></div></main>
